def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    guaranteed_winners = int(supply // WATER_REQ)
    if guaranteed_winners < 0:
        guaranteed_winners = 0

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) > budget:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if isinstance(prev, dict) else None
        if bid is not None:
            prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    severe_danger = hp <= 2 or no_water >= 1
    medium_danger = hp <= 4

    if guaranteed_winners <= 1:
        if severe_danger:
            target = max(92.0, highest_prev + 2.0)
        elif medium_danger:
            target = max(58.0, avg_prev * 0.75)
        else:
            target = 12.0
    else:
        if severe_danger:
            target = max(72.0, avg_prev + 3.0)
        elif medium_danger:
            target = max(46.0, avg_prev * 0.7)
        else:
            target = 24.0

    if highest_prev >= 120 and not severe_danger:
        target = min(target, 20.0)
    elif highest_prev >= 90 and not medium_danger:
        target = min(target, 26.0)

    if urgent_opp >= 2 and not severe_danger:
        target = min(target, 18.0)

    reserve = DAILY_SALARY * 2
    max_affordable = budget - reserve
    if severe_danger:
        max_affordable = budget - DAILY_SALARY * 0.25
    elif medium_danger:
        max_affordable = budget - DAILY_SALARY * 1.0

    if max_affordable < 0:
        max_affordable = budget

    bid = min(target, max_affordable, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents only
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate how many water blocks we can reasonably afford to contest
    # If supply is low, competition matters more; if high, we can bid less.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if (MAX_SUPPLY - MIN_SUPPLY) != 0 else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid: aim to be competitive but not wasteful.
    # When supply is low, increase; when high, decrease.
    base_bid = DAILY_SALARY * (0.62 - 0.18 * supply_ratio)

    # React to Cindy/Alex yesterday: if someone bid extremely high, we must respond.
    # Use the max yesterday bid as pressure signal.
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # If opponent(s) showed extreme pressure (near/above our daily salary), match more.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If we're healthy, slightly undercut; if low HP, bid aggressively.
        if my_status['hp'] > 3:
            bid = DAILY_SALARY * (0.78 - 0.08 * supply_ratio)
        else:
            bid = DAILY_SALARY * (0.95 - 0.05 * supply_ratio)
    else:
        # Otherwise, undercut the typical Cindy-heavy pace by staying around base_bid.
        # If Cindy specifically bid high yesterday, nudge upward; if not, stay near base.
        cindy = opponents_status.get('Cindy', None)
        cindy_prev = (cindy.get('previous_trace', {}) if cindy else {}) or {}
        cindy_bid = cindy_prev.get('bid', None)
        cindy_bid_val = None
        if cindy_bid is not None:
            try:
                cindy_bid_val = float(cindy_bid)
            except Exception:
                cindy_bid_val = None

        if cindy_bid_val is not None and cindy_bid_val >= DAILY_SALARY * 0.75:
            bid = base_bid * 1.15
        else:
            bid = base_bid

    # Survival/triage: if we're in danger, ensure higher bid.
    if my_status['hp'] <= 2:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif my_status['no_water_days'] >= 2:
        bid = max(bid, DAILY_SALARY * 0.72)

    # Budget cap
    bid = float(min(my_status['budget'], bid))

    # If budget is tiny, still bid what we can.
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Find highest previous bid among alive opponents
    highest_prev = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev['bid'] > highest_prev:
                highest_prev = prev['bid']

    # Base bid: try to outbid highest previous by 1.5, but not exceed budget
    base_bid = min(budget, highest_prev + 1.5)

    # Emergency: if out of water for 2+ days, bid high
    if my_status['no_water_days'] >= 2 or hp <= 2:
        return min(budget, DAILY_SALARY * 0.95)

    # Late game: days 7-10, be more aggressive
    if day >= 7:
        return min(budget, max(base_bid, DAILY_SALARY * 0.8))

    # Early game: conserve budget, bid modestly
    if day <= 3:
        return min(budget, max(base_bid, DAILY_SALARY * 0.6))

    # Mid game: moderate
    return min(budget, max(base_bid, DAILY_SALARY * 0.7))
